insert into public.menu_categories (restaurant_id, slug, name, icon, sort_order)
values
  ((select id from public.restaurants where slug = 'mimosa'), 'brunch_classics', '{"fr":"Brunch Classics","ar":"كلاسيكيات البرانش","en":"Brunch Classics"}'::jsonb, 'egg', 1),
  ((select id from public.restaurants where slug = 'mimosa'), 'drunch_savory', '{"fr":"Drunch & Savory","ar":"أطباق مالحة ودورنش","en":"Drunch & Savory"}'::jsonb, 'beef', 2),
  ((select id from public.restaurants where slug = 'mimosa'), 'sweets_pancakes', '{"fr":"Sweets & Pancakes","ar":"حلويات وبانكيك","en":"Sweets & Pancakes"}'::jsonb, 'cake', 3),
  ((select id from public.restaurants where slug = 'mimosa'), 'drinks_cocktails', '{"fr":"Boissons & Cocktails","ar":"مشروبات وموكتيلات","en":"Drinks & Mocktails"}'::jsonb, 'glass-water', 4)
insert into public.menu_items
  (restaurant_id, category_id, slug, name, description, price, image_url, badge, extras, sort_order)
values
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'brunch_classics'), 'brunch-1', '{"fr":"Avocado Toast Prestige","ar":"أفوكادو توست برستيج","en":"Prestige Avocado Toast"}'::jsonb, '{"fr":"Pain au levain toasté, écrasé d’avocat frais au citron vert, œuf poché coulant, graines de grenade et feta émiettée.","ar":"خبز الحبوب المقرمش، هريس الأفوكادو والليمون، بيضة بوشيه، حب الرمان وجبنة الفيتا اليونانية.","en":"Sourdough toast, seasoned mashed avocado with lime, runny poached egg, pomegranate seeds, and feta."}'::jsonb, 1100, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?w=700&auto=format&fit=crop&q=80', '{"fr":"Best Seller","ar":"الأكثر طلباً","en":"Best Seller"}'::jsonb, '[{"name":{"fr":"Saumon fumé extra","ar":"سلمون مدخن إضافي","en":"Extra Smoked Salmon"},"price":450},{"name":{"fr":"Œuf poché supplémentaire","ar":"بيضة بوشيه إضافية","en":"Extra Poached Egg"},"price":150},{"name":{"fr":"Champignons rôtis à l’ail","ar":"فطر بري مشوي","en":"Roasted Garlic Mushrooms"},"price":200}]'::jsonb, 1),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'brunch_classics'), 'brunch-2', '{"fr":"Eggs Benedict Royale","ar":"إيغز بينيديكت رويال","en":"Royal Eggs Benedict"}'::jsonb, '{"fr":"Muffins anglais croustillants, dinde fumée artisanale ou saumon, deux œufs pochés et onctueuse sauce hollandaise dorée.","ar":"مافن إنجليزي محمص، سلمون أو تركي مدخن، بيضتين بوشيه مع صلصة الهولنديز المخملية الفاخرة.","en":"Toasted English muffin, smoked turkey or salmon, two organic poached eggs, silky golden hollandaise."}'::jsonb, 1350, 'https://images.unsplash.com/photo-1608039829572-78524f79c4c7?w=700&auto=format&fit=crop&q=80', '{"fr":"Signature","ar":"توقيع ميموزا","en":"Signature"}'::jsonb, '[{"name":{"fr":"Sauce hollandaise extra","ar":"صلصة هولنديز إضافية","en":"Extra Hollandaise"},"price":150},{"name":{"fr":"Bacon de bœuf croustillant","ar":"بيكون لحم مقرمش","en":"Crispy Beef Bacon"},"price":300}]'::jsonb, 2),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'brunch_classics'), 'brunch-3', '{"fr":"Shakshuka Orientale Gourmande","ar":"شكشوكة شرقية فاخرة","en":"Gourmet Shakshuka"}'::jsonb, '{"fr":"Mijoté traditionnel de tomates confites, poivrons doux, épices douces, œufs fermiers au plat et féta marinée.","ar":"طماطم متبلة ومطهوة ببطء مع الفلفل الحلو، بهارات عطرية، بيض عيون، وجبن الماعز مع خبز دافئ.","en":"Slow-cooked spiced tomato sauce, sweet peppers, baked organic eggs, fresh herbs, and crumbled feta."}'::jsonb, 950, 'https://images.unsplash.com/photo-1590412200988-a436970781fa?w=700&auto=format&fit=crop&q=80', null, '[{"name":{"fr":"Merguez artisanale grillée","ar":"مرقاز محلي مشوي","en":"Grilled Merguez"},"price":350},{"name":{"fr":"Fromage de chèvre fondant","ar":"جبن ماعز ذائب","en":"Melted Goat Cheese"},"price":250}]'::jsonb, 3),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'drunch_savory'), 'drunch-1', '{"fr":"Truffle Angus Sliders (Trio)","ar":"ميني برغر ترافل أنغوس (3 قطع)","en":"Truffle Angus Sliders (Trio)"}'::jsonb, '{"fr":"Trois mini-burgers briochés, bœuf Angus Black, crème de truffe noire, cheddar affiné et oignons caramélisés.","ar":"ثلاث قطع برغر بخبز البريوش، لحم أنغوس عالي الجودة، صوص الترافل الأسود، شيدر معتق وبصل مكرمل.","en":"Trio of soft brioche mini-burgers, Black Angus beef, black truffle aioli, aged cheddar, caramelized onion."}'::jsonb, 1850, 'https://images.unsplash.com/photo-1550547660-d9450f859349?w=700&auto=format&fit=crop&q=80', '{"fr":"Chef Choice","ar":"اختيار الشيف","en":"Chef Choice"}'::jsonb, '[{"name":{"fr":"Frites fraîches au parmesan & truffe","ar":"بطاطس مقرمشة ببارميزان وترفل","en":"Truffle Parmesan Fries"},"price":450},{"name":{"fr":"Double cheddar fondu","ar":"جبن شيدر مضاعف","en":"Double Melted Cheddar"},"price":200}]'::jsonb, 4),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'drunch_savory'), 'drunch-2', '{"fr":"Crispy Korean Chicken Bao","ar":"باو الدجاج المقرمش الكوري","en":"Crispy Korean Chicken Bao"}'::jsonb, '{"fr":"Deux pains bao vapeur ultra moelleux, poulet pané extra croustillant, sauce coréenne sucrée-épicée et pickles.","ar":"خبز الباو الآسيوي المطهو عالبخار، قطع دجاج كرانشي، صوص كوري مميز مع المخلل والخضار المقرمشة.","en":"Steamed fluffy bao buns, crispy buttermilk fried chicken, sweet-spicy glaze, house pickles & sesame."}'::jsonb, 1400, 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=700&auto=format&fit=crop&q=80', null, '[{"name":{"fr":"Bao supplémentaire (1 pièce)","ar":"قطعة باو إضافية","en":"Extra Bao Bun"},"price":500},{"name":{"fr":"Sauce piquante maison","ar":"صلصة حارة خاصة","en":"Spicy House Dip"},"price":100}]'::jsonb, 5),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'drunch_savory'), 'drunch-3', '{"fr":"Burrata Crémeuse aux Pêches Grillées","ar":"سلطة بوراتا إيطالية مع الخوخ المشوي","en":"Creamy Burrata & Grilled Peaches"}'::jsonb, '{"fr":"Burrata entière 150g, pêches caramélisées, tomates cerises confites, pistaches torréfiées et réduction balsamique.","ar":"جبنة بوراتا الإيطالية الطازجة، شرائح خوخ مكرمل، طماطم كرزية، فستق محمص ورذاذ خل البلسمك.","en":"Whole fresh burrata, caramelized peaches, heirloom cherry tomatoes, toasted pistachios, balsamic glaze."}'::jsonb, 1650, 'https://images.unsplash.com/photo-1592417817098-8f3d69102a56?w=700&auto=format&fit=crop&q=80', null, '[{"name":{"fr":"Focaccia tiède au romarin","ar":"خبز فوكاشيا بالأعشاب","en":"Warm Rosemary Focaccia"},"price":250}]'::jsonb, 6),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'sweets_pancakes'), 'sweet-1', '{"fr":"Brioche French Toast Caramel Salé","ar":"فرنش توست بريوش بالكراميل المملح","en":"Salted Caramel French Toast"}'::jsonb, '{"fr":"Pain brioché artisanal doré au beurre doux, caramel beurre salé fait maison, éclats de noisettes et glace vanille Bourbon.","ar":"خبز بريوش محمص بالزبدة، كراميل مملح محضر منزلياً، مكسرات البندق المحمصة وكرة آيسكريم فانيليا.","en":"Golden thick-cut brioche, homemade salted butter caramel, roasted hazelnut crumbs, Bourbon vanilla gelato."}'::jsonb, 1200, 'https://images.unsplash.com/photo-1484723091739-30a097e8f929?w=700&auto=format&fit=crop&q=80', '{"fr":"Incontournable","ar":"الأعلى تقييماً","en":"Must Try"}'::jsonb, '[{"name":{"fr":"Boule de glace vanille","ar":"كرة آيسكريم إضافية","en":"Extra Ice Cream Scoop"},"price":200},{"name":{"fr":"Fruits rouges frais","ar":"فواكه غابية طازجة","en":"Fresh Red Berries"},"price":300}]'::jsonb, 7),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'sweets_pancakes'), 'sweet-2', '{"fr":"Fluffy Soufflé Pancakes","ar":"بانكيك سوفليه ياباني منفوش","en":"Fluffy Japanese Pancakes"}'::jsonb, '{"fr":"Pancakes japonais ultra légers et nuageux, sirop d’érable pur du Canada, chantilly vanillée et myrtilles fraîches.","ar":"بانكيك ياباني خفيف وهش، شراب القيقب الكندي النقي، كريمة شانتيه غنية وحبات التوت الأزرق.","en":"Ultra-light soufflé pancakes, pure Canadian maple syrup, whipped vanilla cream, fresh wild blueberries."}'::jsonb, 1300, 'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=700&auto=format&fit=crop&q=80', null, '[{"name":{"fr":"Chocolat Nutella fondant","ar":"شوكولاتة نوتيلا دافئة","en":"Warm Nutella drizzle"},"price":250},{"name":{"fr":"Pâte de pistache pure","ar":"صوص فستق نقي","en":"Pure Pistachio paste"},"price":350}]'::jsonb, 8),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'sweets_pancakes'), 'sweet-3', '{"fr":"Açaí Bowl Énergétique & Tropical","ar":"أساي بول استوائي منعش","en":"Tropical Acai Energy Bowl"}'::jsonb, '{"fr":"Sorbet d’açaí biologique d’Amazonie, granola croquant, banane, graines de chia, beurre de cacahuète et noix de coco.","ar":"سموذي الأساي العضوي المثلج، غرانولا مقرمشة، موز، بذور الشيا، زبدة الفول السوداني ومبشور جوز الهند.","en":"Organic Amazonian acai smoothie bowl, artisanal granola, banana slices, chia seeds, and peanut butter swirl."}'::jsonb, 1150, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?w=700&auto=format&fit=crop&q=80', null, '[{"name":{"fr":"Beurre d’amande bio","ar":"زبدة لوز عضوية","en":"Organic Almond Butter"},"price":250}]'::jsonb, 9),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'drinks_cocktails'), 'drink-1', '{"fr":"Mimosa Signature (Sans Alcool)","ar":"موكتيل ميموزا المنعش (بدون كحول)","en":"Mimosa Signature Mocktail"}'::jsonb, '{"fr":"Jus d’orange fraîchement pressé, purée de pêche blanche, eau pétillante infusée et romarin frais.","ar":"عصير برتقال طبيعي معصور على البارد، بيوريه الخوخ الأبيض، صودا فوارة مع لمسة إكليل الجبل العطرة.","en":"Fresh squeezed orange juice, white peach purée, sparkling water, garnished with fresh rosemary."}'::jsonb, 650, 'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=700&auto=format&fit=crop&q=80', '{"fr":"Iconic","ar":"الأيقوني","en":"Iconic"}'::jsonb, '[{"name":{"fr":"Sirop de framboise sauvage","ar":"سيروب توت بري","en":"Wild Raspberry Syrup"},"price":100}]'::jsonb, 10),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'drinks_cocktails'), 'drink-2', '{"fr":"Iced Ceremonial Matcha Latte","ar":"ماتشا لاتيه مثلج درجة احتفالية","en":"Iced Ceremonial Matcha Latte"}'::jsonb, '{"fr":"Matcha Uji de première récolte du Japon, lait d’avoine velouté, touche de vanille de Madagascar.","ar":"ماتشا أوجي اليابانية الفاخرة، حليب الشوفان الكريمي، مع نفحات فانيليا مدغشقر المنعشة.","en":"First harvest Japanese ceremonial matcha, silky oat milk, sweetened lightly with Madagascar vanilla."}'::jsonb, 750, 'https://images.unsplash.com/photo-1536256263959-770b48d82b0a?w=700&auto=format&fit=crop&q=80', null, '[{"name":{"fr":"Cold Foam Fraise maison","ar":"رغوة فراولة باردة","en":"Strawberry Cold Foam"},"price":200}]'::jsonb, 11),
  ((select id from public.restaurants where slug = 'mimosa'), (select c.id from public.menu_categories c join public.restaurants r on r.id = c.restaurant_id where r.slug = 'mimosa' and c.slug = 'drinks_cocktails'), 'drink-3', '{"fr":"Cold Brew Éthiopien Yirgacheffe","ar":"كولد برو إثيوبي مقطر ببطء","en":"Ethiopian Cold Brew"}'::jsonb, '{"fr":"Café de spécialité infusé à froid pendant 18 heures. Notes florales de jasmin et bergamote.","ar":"قهوة مختصة مقطرة على البارد لمدة 18 ساعة، بطعم الزهور وفاكهة البرغموت الطبيعية.","en":"Specialty coffee steep-brewed for 18 hours. Crisp floral jasmine notes and bright citrus finish."}'::jsonb, 600, 'https://images.unsplash.com/photo-1517701550927-30cf4ba1dba5?w=700&auto=format&fit=crop&q=80', null, '[{"name":{"fr":"Sirop noisette grillée","ar":"سيروب بندق محمص","en":"Roasted Hazelnut Syrup"},"price":100}]'::jsonb, 12)
