-- Seed Mimosa's existing multilingual menu into the RestoMenu tenant database.
-- Run after 20261120000000_restomenu_multitenant.sql.

on conflict (restaurant_id, slug) do update set
  name = excluded.name,
  icon = excluded.icon,
  sort_order = excluded.sort_order;

on conflict (restaurant_id, slug) do update set
  category_id = excluded.category_id,
  name = excluded.name,
  description = excluded.description,
  price = excluded.price,
  image_url = excluded.image_url,
  badge = excluded.badge,
  extras = excluded.extras,
  sort_order = excluded.sort_order;

-- The loader reads only active categories and available products.